import tomllib
from pathlib import Path
def configured_mode(config_path=Path('config/runtime.toml')):
    with config_path.open('rb') as stream:
        return tomllib.load(stream)['mode']
def save(mode, path, value):
    if mode == 'memory':
        return {'value': value}
    path.write_text(value, encoding='utf-8')
    return path
def save_configured(path, value, config_path=Path('config/runtime.toml')):
    return save(configured_mode(config_path), path, value)

